const fs=require('fs'),assert=require('node:assert/strict'),{chromium}=require('playwright');
(async()=>{const browser=await chromium.launch({executablePath:'/usr/bin/chromium',args:['--no-sandbox']}),page=await browser.newPage({reducedMotion:'reduce',hasTouch:true}),errors=[],rows=[];page.on('pageerror',e=>errors.push(e.message));const root=process.env.ROOT+'/lol-coach/',out=process.env.OUT;
for(const [device,width,height]of[['desktop',1440,1000],['mobile',390,844]]){await page.setViewportSize({width,height});await page.goto(root+'loading.html');await page.waitForSelector('#analyze:enabled');await page.locator('#example-0').click();await page.locator('#analyze').click();const h=page.locator('#loading-coach');await h.locator('[data-coach-focus=tab-fight]').click();for(const area of ['lane','operations','fight']){await h.locator('[data-coach-focus=tab-'+area+']').click();const summary=h.locator('[data-action-summary='+area+']');await summary.waitFor();assert.equal(await summary.locator('[data-action-kind]').count(),5);assert.equal(await h.locator('.coach-panel > div > :first-child').getAttribute('data-action-summary'),area);for(let i=0;i<5;i++){const row=summary.locator('[data-action-kind]').nth(i),key=await row.getAttribute('data-action-target');await row.click();const target=h.locator('[data-action-detail='+key+']');assert(await target.isVisible());assert.equal(await target.evaluate(e=>e===document.activeElement),true);}await summary.evaluate(n=>n.scrollIntoView({block:'start',behavior:'instant'}));await page.screenshot({path:out+'/'+device+'-summary-'+area+'.png'});}const f=h.locator('.formation-explorer');await f.locator('.formation-arena').waitFor();if(device==='mobile'){await page.setViewportSize({width:320,height:844});for(const area of ['lane','operations','fight']){await h.locator('[data-coach-focus=tab-'+area+']').tap();await page.evaluate(()=>document.documentElement.style.fontSize='200%');assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),area+' 320/200% overflow');await page.evaluate(()=>document.documentElement.style.fontSize='');}await page.setViewportSize({width:390,height:844});}assert.equal(await f.locator('main').count(),0);assert.equal(await f.locator('.formation-actor').count(),10);assert.equal(await f.locator('[data-range-champion]').count(),2);assert(await f.locator('.formation-arena').evaluate(e=>{const c=e.querySelector('[data-range-champion=Caitlyn]'),p=e.querySelector('[data-formation-champion=Caitlyn] .formation-portrait').getBoundingClientRect(),r=e.getBoundingClientRect();return Math.abs(p.x+p.width/2-r.x-Number(c.getAttribute('cx'))/100*r.width)<2&&Math.abs(p.y+p.height/2-r.y-Number(c.getAttribute('cy'))/100*r.height)<2;}));assert.equal(await f.locator('.is-self').getAttribute('data-formation-champion'),'Caitlyn');if(device==='mobile')await f.locator('[data-formation-control=range-OFF]').tap();else await f.locator('[data-formation-control=range-OFF]').click();assert.equal(await f.locator('[data-range-champion]').count(),0);await f.locator('[data-formation-control=links]').click();assert.equal(await f.locator('.formation-connection').count(),0);await f.locator('[data-formation-control=range-CARRIES]').click();await f.locator('[data-formation-control=links]').click();assert.equal(await f.locator('[data-range-champion]').count(),2);assert(await f.locator('.formation-connection').count()>0);const action_items=await h.locator('[data-action-summary=fight] [data-action-kind]').allTextContents();let summary=[];
for(const scene of ['FRONT_CONNECTED','FLANK_ISOLATE']){await f.locator('[data-formation-control='+scene+']').click();for(let step=0;step<3;step++){await f.locator('[data-formation-control=step-'+step+']').click();assert.equal(await f.locator('.formation-arena').first().getAttribute('data-formation-step'),String(step));const overlap=await f.locator('.formation-portrait').evaluateAll(ns=>{const rs=ns.map(n=>n.getBoundingClientRect());return rs.flatMap((a,i)=>rs.slice(i+1).filter(b=>Math.min(a.right,b.right)>Math.max(a.left,b.left)+1&&Math.min(a.bottom,b.bottom)>Math.max(a.top,b.top)+1).map(()=>i));});assert.deepEqual(overlap,[],scene+' '+step+' overlapping portraits');assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));summary.push({scene,step,text:await f.locator('.formation-action').innerText()});}await f.locator('[data-formation-control=step-1]').click();assert(await f.locator('.formation-arena').evaluate(e=>Math.abs(e.getBoundingClientRect().width-e.getBoundingClientRect().height)<2));await f.evaluate(n=>n.scrollIntoView({block:'start',behavior:'instant'}));await page.screenshot({path:out+'/'+device+'-'+scene+'.png'});}
await f.locator('[data-formation-control="ENEMY:Kaisa"]').click();assert.match(await f.locator('.formation-actor-detail').innerText(),/카이사/);assert.equal(await f.locator('[data-range-champion]').first().getAttribute('data-range-champion'),'Kaisa');await f.locator('[data-formation-zoom]').click();const dialog=f.locator('dialog');assert(await dialog.isVisible());await dialog.locator('[data-formation-control=FRONT_CONNECTED]').click();await dialog.locator('[data-formation-control=step-2]').click();assert.equal(await f.locator('.formation-arena').first().getAttribute('data-formation-scene'),'FRONT_CONNECTED');assert.equal(await f.locator('.formation-arena').first().getAttribute('data-formation-step'),'2');await page.keyboard.press('Escape');assert(await dialog.isHidden());await page.waitForFunction(()=>document.activeElement?.hasAttribute('data-formation-zoom'),{},{timeout:1500});assert.equal(await page.evaluate(()=>document.activeElement?.hasAttribute('data-formation-zoom')),true,'zoom must restore current opener after scene/step rerender');await f.locator('[data-formation-control=FLANK_ISOLATE]').first().focus();await page.keyboard.press('Enter');assert.equal(await f.locator('.formation-arena').first().getAttribute('data-formation-scene'),'FLANK_ISOLATE');
await page.locator('#input-panel').evaluate(n=>n.open=true);for(const [i,id]of ['Malphite','Ivern','Ziggs','Kaisa','Janna'].entries())await page.locator('#pick-ENEMY-'+i).fill(id);await page.locator('#analyze').click();await h.locator('[data-coach-focus=tab-fight]').click();await f.locator('[data-formation-control=FLANK_ISOLATE]').click();await f.locator('[data-formation-control=step-1]').click();assert(await f.locator('.formation-portrait').evaluateAll(ns=>{const rs=ns.map(n=>n.getBoundingClientRect());return rs.every((a,i)=>rs.slice(i+1).every(b=>a.right<=b.left||b.right<=a.left||a.bottom<=b.top||b.bottom<=a.top));}),'non-flanking supported variant must not overlap');await f.evaluate(n=>n.scrollIntoView({block:'start',behavior:'instant'}));await page.screenshot({path:out+'/'+device+'-variant-no-overlap.png'});await page.locator('#input-panel').evaluate(n=>n.open=true);await page.locator('#pick-ENEMY-3').fill('징크스');assert(await page.locator('#loading-results').isHidden());await page.locator('#analyze').click();await h.locator('[data-coach-focus=tab-fight]').click();assert.equal(await h.locator('.formation-arena').count(),0);assert.match(await h.locator('.formation-explorer').innerText(),/지원/);
await page.goto(root+'directions.html');await page.locator('#formation-study .formation-arena').waitFor();assert.equal(await page.locator('#formation-study .formation-actor').count(),10);assert.equal(await page.locator('.scene-card').count(),6);await page.locator('#formation-study [data-formation-control=FLANK_ISOLATE]').click();await page.locator('#formation-study').evaluate(n=>n.scrollIntoView({block:'start',behavior:'instant'}));await page.screenshot({path:out+'/'+device+'-learning.png'});if(device==='mobile'){await page.setViewportSize({width:320,height:844});assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await page.evaluate(()=>document.documentElement.style.fontSize='200%');assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));}rows.push({device,summary,action_items});}
assert.deepEqual(errors,[]);fs.writeFileSync(out+'/result.json',JSON.stringify({passed:true,rows,errors,coaching_accuracy:null,live_positions:false},null,2));await browser.close();})().catch(e=>{console.error(e);process.exit(1)});
